use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " Clips text content based on line count and optionally truncates long lines"] fn clip_by_lines (content : & str , prefix_lines : usize , suffix_lines : usize , max_line_length : usize ,) -> (Vec < String > , Option < (usize , usize) > , usize) { let mut truncated_lines_count = 0 ; let lines = content . lines () . map (| line | { if line . chars () . count () > max_line_length { truncated_lines_count += 1 ; let truncated : String = line . chars () . take (max_line_length) . collect () ; let extra_chars = line . chars () . count () - max_line_length ; format ! ("{truncated}...[{extra_chars} more chars truncated]" ,) } else { line . to_string () } }) . collect :: < Vec < _ > > () ; let total_lines = lines . len () ; if total_lines <= prefix_lines . saturating_add (suffix_lines) { return (lines . into_iter () . collect () , None , truncated_lines_count) ; } let mut result_lines = Vec :: new () ; for line in lines . iter () . take (prefix_lines) { result_lines . push (line . to_string ()) ; } for line in lines . iter () . skip (total_lines - suffix_lines) { result_lines . push (line . to_string ()) ; } let hidden_lines = total_lines - prefix_lines - suffix_lines ; (result_lines , Some ((prefix_lines , hidden_lines)) , truncated_lines_count ,) }